import moment from "moment";
import Vue from "vue";
import axios from "axios";

export function description() {
    return {
        name: "DisplayName",
        header: "Name",
        sortable: true,
        type: "html",
        indicate() {
            return "none";
        },
        format(value, data) {
            if (data.ShareOrDelegate) {
                if (data.InstanceKey) value = `(${data.InstanceKey}) ${value}`;
                if (data.RelatesTo) {
                    value = `${data.RelatesTo} - ${value}`;
                }
                value += `<span class="tag ${data.ShareOrDelegate.toLowerCase()}">${
                    data.SharedBy
                }</span>`;
            } else if (data.RelatesTo) {
                value = `${data.RelatesTo} - ${value}`;
            }
            return value;
        }
    };
}

export function stateName(tab) {
    let header = "Current State";
    if (tab === "Completed")
    {
        header = "Final State";
    }
    return {
        name: "CurrentState",
        header: header,
        sortable: true
    };
}

export function stateAssigneeName() {
    return {
        name: "StateAssigneeName",
        header: "Assigned To",
        sortable: true
    };
}

export function stateEnteredAt(tab) {
    let header = "Date Assigned";
    if (tab === "Completed")
    {
        header = "Date Completed";
    }
    else if (tab === "ToAction")
    {
        header = "Date Received";
    }
    return {
        name: "StateEnteredAt",
        header: header,
        type: "date",
        sortable: true,
        format(value) {
            return moment(value).format("DD/MM/YYYY h:mm a");
        }
    };
}

export function completedBy(tab) {
    return {
        name: "CompletedBy",
        header: "Completed By",
        sortable: true
    };
}

export function effectiveDate() {
    return {
        name: "EffectiveDate",
        header: "Effective Date",
        type: "date",
        sortable: false,
        format(value) {
            if (value === null || value.toString().toLowerCase().trim() === 'null' || value.toString().trim() === '') return '';
            return moment(value).format("DD/MM/YYYY");
        }
    };
}

